-- Minimal Supabase-like schema used ONLY by the SQL trigger tests.
-- Mirrors the columns of the live tables the migration-004 triggers touch.

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN CREATE ROLE service_role; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN CREATE ROLE authenticated; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN CREATE ROLE anon; END IF;
END $$;

CREATE SCHEMA IF NOT EXISTS auth;
CREATE OR REPLACE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS
$$ SELECT nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;

CREATE PUBLICATION supabase_realtime;

CREATE TABLE public.users (
    user_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username VARCHAR(255) UNIQUE NOT NULL,
    password VARCHAR(255) NOT NULL,
    name VARCHAR(255), mob VARCHAR(50), status VARCHAR(30) DEFAULT 'ACTIVE',
    created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE TABLE public.admin_users (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id UUID, email TEXT, role TEXT, status TEXT DEFAULT 'ACTIVE'
);
CREATE TABLE public.inventory_items (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL, price NUMERIC(10,2), current_stock INT NOT NULL DEFAULT 0,
    minimum_stock INT DEFAULT 5, status TEXT, updated_at TIMESTAMPTZ
);
CREATE TABLE public.inventory_transactions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    item_id BIGINT, type TEXT, quantity INT, previous_stock INT, new_stock INT,
    reason TEXT, notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE TABLE public.equipment_orders (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id BIGINT NOT NULL, equipment_id BIGINT NOT NULL, quantity INT NOT NULL DEFAULT 1,
    total_price NUMERIC(10,2) NOT NULL DEFAULT 0, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION,
    status VARCHAR(50) DEFAULT 'Pending', created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE TABLE public.complaints (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username VARCHAR(255) NOT NULL, category VARCHAR(100), description TEXT,
    priority TEXT, status VARCHAR(50) DEFAULT 'Pending', created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE TABLE public.sos_incidents (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id BIGINT, username TEXT, emergency_type TEXT, latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION, location_name TEXT, status TEXT DEFAULT 'ACTIVE',
    created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE TABLE public.razorpay_payments (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    razorpay_order_id TEXT, user_id BIGINT, amount_paise INT, currency TEXT DEFAULT 'INR',
    status TEXT DEFAULT 'PENDING', failure_reason TEXT, created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE TABLE public.guide (g_id BIGINT PRIMARY KEY, name TEXT);
CREATE TABLE public.guide_bookings (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username TEXT, guide_id BIGINT, status TEXT, created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE TABLE public.offers (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title TEXT, status TEXT, start_date DATE, end_date DATE, created_at TIMESTAMPTZ DEFAULT NOW()
);
